  final mapList = <int>[];
  for (var fieldIdx = 0; fieldIdx < propertyAliases.length; fieldIdx++) {
    for (final alias in propertyAliases[fieldIdx]) {
      flatKeys.add(alias);
      mapList.add(fieldIdx);
